Definition READSOME_STACK : Z := 64 + MTX_UNLOCK_STACK.       (* [comment removed for export] *)
Definition LOC_TS_EOF : Z := 0x7c2d8.                        (* [comment removed for export] *)
Definition EC_ts_eof : ecv := ec_make_loc ASIO_ERR_EOF G_MISC_CAT_INST LOC_TS_EOF.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition rs_take (ds : list byte) (tn : Z) : Z := Z.min (zlength ds) tn.

(* [comment removed for export] *)
Definition rs_state (S : statev) (ds : list byte) (tn : Z) : statev :=
  mkST (st_hdr S) 0
       (if zlength ds =? 0 then st_fb S else fb_consume (st_fb S) (rs_take ds tn))
       (st_code S) (st_nread S + 1) (st_nread_bytes S + rs_take ds tn).

