Definition hidden (P : Prop) : Prop := P.
Lemma hide : forall P : Prop, P -> hidden P. Proof. exact (fun P p => p). Qed.
Ltac hideH H := apply hide in H.
Ltac showH H := unfold hidden in H.

(* [comment removed for export] *)
Ltac side := first [ eassumption
                   | rewrite ?unsigned_lit by lia; first [ eassumption | reflexivity | lia ]
                   | lia ].

(* [comment removed for export] *)
Ltac arrow bs stateb lo :=
  let SPA := fresh "SPA" in
  pose proof sp_arrow_state_spec as SPA; unfold sp_arrow_stmt, P_SP_STATE_ARROW, SP_ARROW_STACK, wz in SPA;
  callZ (SPA bs (stateb + 32) lo); [side.. | ]; clear SPA; unfold wz;
  match goal with P : stk _ _ _ _ |- _ => rename P into ST end.

(* [comment removed for export] *)
Ltac finish_with tac :=
  apply evt_done;
  lazymatch goal with |- ?P ?ms => try unfold P end;
  hnf;
  repeat (lazymatch goal with |- ex _ => eexists end);
  lazymatch goal with
  | |- _ = _ /\ _ => split; [ cbv delta [mkR]; repeat first [ reflexivity | f_equal ]; tac | ]
  | |- _ = _ => cbv delta [mkR]; repeat first [ reflexivity | f_equal ]; tac
  end;
  repeat match goal with |- _ /\ _ => split end; try assumption.

(* [comment removed for export] *)
Lemma StateBlock_open : forall LB m b ioc implb S ds,
  StateBlock LB m b ioc implb S ds ->
  exists p j7 j16 j4,
    In (p, b, SZ_SPCI_STATE) LB /\ rblock_range b SZ_SPCI_STATE
    /\ rw_cells rsegs m b (SpcHdrCells (st_hdr S) j7) /\ spc_ok (st_hdr S) /\ spc_vptr (st_hdr S) = VP_SPCI_STATE
    /\ rw_cells rsegs m (b + 32) (AnyExecCells (b + 32) ioc j16)
    /\ rw_cells rsegs m (b + 88) [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)]
    /\ PMutex m (b + 104) (st_lk S)
    /\ FlatBuf LB m (b + 144) (st_fb S) ds
    /\ PCond m (b + 192) 0
    /\ rw_cells rsegs m (b + 240)
         [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
          C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)]
    /\ (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) /\ 0 <= st_nread S < 2^63 /\ 0 <= st_nread_bytes S < 2^63.
Proof.
  intros LB m b ioc implb S ds (p & j7 & j16 & j4 & H). exists p, j7, j16, j4.
  unfold O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP in H.
  replace (b + 32 + 0) with (b + 32) in H by lia. replace (b + 32 + 56) with (b + 88) in H by lia.
  replace (b + 32 + 72) with (b + 104) in H by lia. replace (b + 32 + 112) with (b + 144) in H by lia.
  replace (b + 32 + 160) with (b + 192) in H by lia. replace (b + 32 + 208) with (b + 240) in H by lia.
  exact H.
Qed.

Lemma StateBlock_close : forall LB m b ioc implb S ds p j7 j16 j4,
    In (p, b, SZ_SPCI_STATE) LB -> rblock_range b SZ_SPCI_STATE ->
    rw_cells rsegs m b (SpcHdrCells (st_hdr S) j7) -> spc_ok (st_hdr S) -> spc_vptr (st_hdr S) = VP_SPCI_STATE ->
    rw_cells rsegs m (b + 32) (AnyExecCells (b + 32) ioc j16) ->
    rw_cells rsegs m (b + 88) [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)] ->
    PMutex m (b + 104) (st_lk S) ->
    FlatBuf LB m (b + 144) (st_fb S) ds ->
    PCond m (b + 192) 0 ->
    rw_cells rsegs m (b + 240)
         [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
          C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)] ->
    (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) -> 0 <= st_nread S < 2^63 -> 0 <= st_nread_bytes S < 2^63 ->
  StateBlock LB m b ioc implb S ds.
Proof.
  intros. exists p, j7, j16, j4.
  unfold O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP.
  replace (b + 32 + 0) with (b + 32) by lia. replace (b + 32 + 56) with (b + 88) by lia.
  replace (b + 32 + 72) with (b + 104) by lia. replace (b + 32 + 112) with (b + 144) by lia.
  replace (b + 32 + 160) with (b + 192) by lia. replace (b + 32 + 208) with (b + 240) by lia.
  repeat (split; [assumption|]). assumption.
Qed.

