(* [comment removed for export] *)
Definition rs_consume_post (ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (stateb k : Z) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x39424) fc None m' (seg_rom rsegs)
    /\ munch [(stateb + 152, stateb + 168)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' (stateb + 144) (FlatBufCells (fb_consume FB k)).

Lemma rs_consume : forall (stateb k : Z) (FB : fbv) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m (stateb + 144) (FlatBufCells FB) ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_last FB <= fb_end FB -> fb_end FB <= hceil ->
  0 <= k <= fb_size FB ->
