(* [comment removed for export] *)
Definition rs_tail_post (sp gp tp s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rav s0v s1v s2v s3v s4v : word) (res M lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v (Z_to_bv 64 res) a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (M, M + 40)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ PMutex m' M 0.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma rs_tail : forall (res M lo : Z) (rav s0v s1v s2v s3v s4v : word) (j7 : list byte)
    sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 ra
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m (bv_unsigned sp + -64)
     [C8 (Z_to_bv 64 M); C1 (Z_to_bv 8 1); CB 7 j7; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  PMutex m M EBUSY ->
  stk rsegs m lo (bv_unsigned sp + -64) -> lo + READSOME_STACK <= bv_unsigned sp -> hceil <= lo ->
  0 < M -> M + 40 <= hceil ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (rs_tail_post sp gp tp s5 s6 s7 s8 s9 s10 s11 F fc rav s0v s1v s2v s3v s4v res M lo m)
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 (Z_to_bv 64 res) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
